import React from 'react';
import styled from 'styled-components';

const FooterWrapper = styled.footer`
  background: #fceabb;
  padding: 1rem;
  text-align: center;
  color: #333;
  font-size: 0.9rem;
`;

const Footer = () => (
    <FooterWrapper>
        © {new Date().getFullYear()} Zoo Shop — Все права защищены
    </FooterWrapper>
);

export default Footer;
